discrete SolarCollectorSystem
port:
    event input real SunlightIntensity;
    event output real HeatEnergy;
state:
    initial state InitialState
        when entry() then
            statehold(1);
        end;

        when receive(SunlightIntensity) then
            transition(WorkingState);
        end;

        when receive(SunlightIntensity) then
            transition(InitialState);
        end;
    end;

    state WorkingState
        when entry() then
            statehold(1);
        end;

        when receive(SunlightIntensity) then
            transition(InitialState);
        end;

        when timeover() then
            transition(FaultState);
            out
                send(HeatEnergy, 1);
        end;
    end;

    state FaultState
        when entry() then
            statehold(1);
        end;

        when timeover() then
            transition(InitialState);
        end;
    end;
end;
end;

discrete ThermalConversionSystem
port:
    event input real HeatEnergy;
    event output real ElectricalEnergy;
state:
    initial state InitialState
        when entry() then
            statehold(1);
        end;

        when receive(HeatEnergy) then
            transition(WorkingState);
        end;

        when timeover() then
            transition(InitialState);
        end;
    end;

    state WorkingState
        when entry() then
            statehold(1);
        end;

        when receive(HeatEnergy) then
            transition(InitialState);
            out
                send(ElectricalEnergy, 1);
        end;

        when timeover() then
            transition(FaultState);
        end;
    end;

    state FaultState
        when entry() then
            statehold(1);
        end;

        when timeover() then
            transition(InitialState);
        end;
    end;
end;
end;

discrete PowerOutputSystem
port:
    event input real ElectricalEnergy;
    event output real PowerOutput;
state:
    initial state InitialState
        when entry() then
            statehold(1);
        end;

        when receive(ElectricalEnergy) then
            transition(WorkingState);
        end;

        when timeover() then
            transition(InitialState);
        end;
    end;

    state WorkingState
        when entry() then
            statehold(1);
        end;

        when receive(ElectricalEnergy) then
            transition(InitialState);
            out
                send(PowerOutput, 0);
        end;

        when timeover() then
            transition(FaultState);
            out
                send(PowerOutput, 0);
        end;

        when receive(ElectricalEnergy) then
            transition(WorkingState);
            out
                send(PowerOutput, 1);
        end;
    end;

    state FaultState
        when entry() then
            statehold(1);
        end;

        when timeover() then
            transition(InitialState);
        end;
    end;
end;
end;

couple SolarThermalPowerSystem
import architectureModels.SolarCollectorSystem as SolarCollector;
import architectureModels.ThermalConversionSystem as ThermalConverter;
import architectureModels.PowerOutputSystem as PowerOutput;

part:
    SolarCollector collectorInstance;
    ThermalConverter converterInstance;
    PowerOutput powerOutputInstance;

connection:
    connect(collectorInstance.HeatEnergy, converterInstance.HeatEnergy);
    connect(converterInstance.ElectricalEnergy, powerOutputInstance.ElectricalEnergy);
end;
